import{_ as e,o as i,c as l,a0 as r}from"./chunks/framework.Cx-5KwGw.js";const p=JSON.parse('{"title":"Смелов Алексей Владиславович - резюме","description":"","frontmatter":{},"headers":[],"relativePath":"cv.md","filePath":"cv.md"}'),o={name:"cv.md"};function t(n,a,c,s,d,h){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="смелов-алексеи-владиславович-резюме" tabindex="-1">Смелов Алексей Владиславович - резюме <a class="header-anchor" href="#смелов-алексеи-владиславович-резюме" aria-label="Permalink to &quot;Смелов Алексей Владиславович - резюме&quot;">​</a></h1><p>г. Новосибирск<br> Email: <a href="mailto:savador@gmail.com" target="_blank" rel="noreferrer">savador@gmail.com</a><br> Возраст: 57 лет</p><h2 id="образование" tabindex="-1">Образование <a class="header-anchor" href="#образование" aria-label="Permalink to &quot;Образование&quot;">​</a></h2><p>1990 - 1995 Новосибирская Государственная Академия Телекоммуникаций и Информатики<br> Факультет Автоматической Электросвязи<br> Специальность: Инженер электросвязи</p><h2 id="опыт-работы" tabindex="-1">Опыт работы <a class="header-anchor" href="#опыт-работы" aria-label="Permalink to &quot;Опыт работы&quot;">​</a></h2><p>2024 по настоящее время - ООО «Модульные Системы Торнадо»<br> Должность: Специалист по технической документации<br> Должностные обязанности:</p><ul><li>Создание и поддержание в актуальном состоянии комплекта программной документации для пакета «Торнадо 2.0» - программной части автоматизированной системы управления технологическими процессами для ТЭЦ и ГРЭС Сибирской генерирующей компании;</li><li>Подготовка документации для регистрации ПО и программно-аппаратного комплекса Торнадо-N в реестрах Минцифры и Минпромторга в рамках импортозамещения систем управления объектами критической инфраструктуры;</li><li>Участие в аналитике и разработке бизнес-процессов внутри ООО «Модульные Системы Торнадо» для оптимизации взаимодействия и лучшей управляемости подразделениями;</li><li>Аналитика технологических процессов на предприятиях углеобогащения в целях изучения возможности импортозамещения на такого рода объектах зарубежных АСУТП на ПТК «Торнадо-N». Посещение предприятий, изучение состава сигналов для систем управления, характеристик оборудования и ПО имеющихся АСУТП, подготовка отчетов и сравнительных таблиц.</li></ul><hr><p>2019 - 2024 - ООО &quot;Городские теплицы Москва&quot;<br> Должность: Специалист по документационному обеспечению\\</p><h3 id="должностные-обязанности" tabindex="-1">Должностные обязанности: <a class="header-anchor" href="#должностные-обязанности" aria-label="Permalink to &quot;Должностные обязанности:&quot;">​</a></h3><ul><li>Организация и ведение документальной базы по продуктам и технологиям iFarm на русском и английском языке;</li><li>Написание технических и агротехнических инструкций, мануалов, регламентов, технических и коммерческих описаний, справочников и т.д.</li><li>Создание клиентских разделов в Confluence для доступа к документационной базе.</li><li>Разработка принципов наименования и обозначения изделий iFarm, ведение базы данных наименований и обозначений.Разработка принципов наименования и обозначения проектов вертикальных ферм, ведение соответствующей базы данных.</li><li>Ведение работы, связанной с интеллектуальной собственностью (патенты и товарные знаки).</li><li>В качестве дополнительной нагрузки: ведение работы с российскими и зарубежными поставщиками различных автоматизированных линий для теплиц в качестве заказчика.</li><li>В качестве дополнительной нагрузки: привлечение к работе с зарубежными партнерами и клиентами в рамках проектов департамента R&amp;D как технический эксперт.\\</li></ul><h3 id="опыт-и-достижения" tabindex="-1">Опыт и достижения: <a class="header-anchor" href="#опыт-и-достижения" aria-label="Permalink to &quot;Опыт и достижения:&quot;">​</a></h3><ul><li>Полностью с нуля создал базу документации группы компаний iFarm на русском и английском языке, как содержательную, так и реквизитную ее части. Сначала база была в Google Drive, затем переехала в Confluence.</li><li>Большой опыт копирайтинга и систематизации документов.</li><li>Разработал систему наименований и обозначений изделий iFarm, пользуясь ГОСТ на ЕСКД, как образцом.</li><li>Сделал несколько патентных заявок на изобретения и полезные модели, которые стали патентами.</li><li>Обеспечил подразделений компании регламентами и бизнес-процессами.</li><li>Обеспечил диалог департамента R&amp;D со швейцарским заказчиком Yasai для решения технических вопросов при реализации проекта вертикальной фермы в Цюрихе. 2011 - 2019ООО «Аилайн Кэмьюникейшнс СНГ»Должность: Директор по международным рынкам.Должностные обязанности:Организация и ведение документальной базы компании;Составление коммерческих и технических документов на русском и английском языках;Опыт и достижения:Участие в рабочей группе GSMA по интерконнекту, подготовка документов к заседаниям, доклад по предмету USSD интерконнекта на заседании группы в Лондоне, доклад в штаб-квартире Vodafone Group в Ньюбери;Подготовка документов на русском и английском языках для вывода продукта компании на ICO. 2009 - 2011ЗАО «Синтерра-Сибирь»Должность: Технический директорДолжностные обязанности:Развертывание сети IP/MPLS на территории Сибири;Строительство сетей местной и зоновой телефонной связи в ряде регионов СФО;Строительство сетей широкополосного доступа. 2005 - 2009ООО «Аилайн Кэмьюникейшнс СНГ»Должность: Директор по международным рынкам.Должностные обязанности:Руководство международными проектами, взаимодействие с партнерами за рубежом;Менеджмент продуктов.Опыт и достижения:Участие в телекоммуникационных выставках и конференциях в Сингапуре, Малайзии, Китае. Выступления на международных конференциях и в рабочих группах по тематике мобильных VAS и технологий, лежащих в их основе.Написание патентных заявок на разработки компании; в результате получены российские патенты на два изобретения и две системы, на одно изобретение получен международный приоритет.Авторство и руководство разработкой сервиса ArrivedOK, который стал официальным лауреатом ежегодного всемирного конкурса Webby Awards 2009 в двух номинациях. 2004 - 2005ОАО «Мобильные ТелеСистемы», филиал «Макрорегион Сибирь»Должность: Начальник отдела развития продуктов и услуг.Должностные обязанности:Развитие дополнительных неголосовых сервисов мобильного оператора, развитие и популяризация мобильного интернета;Внедрение технологических платформ для размещения мобильных сервисов.Опыт и достижения:Организация и налаживание взаимодействия Отдела развития продуктов и услуг с другими подразделениями Макрорегиона «Сибирь» в период структурной реформы ОАО «МТС». [Дата не указана, предположительно 2000-2004]ЗАО «Сибирские Сотовые Системы - 900»Должность: Директор по новым технологиям и услугам.Должностные обязанности:Развитие дополнительных неголосовых сервисов мобильного оператора, мобильного интернета;Внедрение технологических платформ для размещения мобильных сервисов;Развитие и поддержка международного роуминга;Взаимодействие с международной ассоциацией GSM.Опыт и достижения:ЗАО «ССС-900» был вторым оператором GSM в России, запустившим систему передачи данных GPRS.Внедрение первой в России системы мобильных платежей SimMP на базе SIM карт Gem Plus.Организация кампании по переводу нумерации CCC-900 в диапазон МТС, в которой были задействованы все без исключения структурные подразделения CCC-900.Налаживание взаимодействия с провайдерами мобильных неголосовых сервисов в период становления рынка мобильных VAS.Работа в TWG, рабочей группе по терминалам при Международной Ассоциации GSM. Создание постоянного справочного документа GSMA (TW.12), являющегося руководством по поддержке кириллицы и Русского языка, а также других не-латинских алфавитов для производителей мобильных телефонов. 1997 - 2000ЗАО «Сибирские Сотовые Системы - 900»Должность: Директор по роумингу.Должностные обязанности:Развитие и поддержка международного роуминга;Закупки и логистика SIM карт;Взаимодействие с международной ассоциацией GSM.Опыт и достижения:Организация роуминговых отношений более чем с 200 операторами GSM более чем в 100 странах мира. Одна из самых широких география роуминга среди российских операторов GSM в тот период.Ключевая роль в организации на базе ЗАО «ССС-900» Координирующего оператора по Сибирскому Укрупненному Региону согласно приказа Госкомсвязи. Организация международного и национального роуминга для областных операторов GSM в Сибирском регионе. Взаимодействие с международной Ассоциацией GSM по этому вопросу. 1995 - 1997Российско-Германское СП «Ижтел»Должность: Инженер отдела технического сбыта.Должностные обязанности:Определение конфигурации цифровых АТС «Siemens» в зависимости от потребностей заказчика;Формирование конфигурационных файлов при помощи специального ПО;Проведение дизайн-митингов с заказчиками. Опыт использования специализированного программного обеспеченияMicrosoft Project, OpenProj для Macintosh, GanttPRO, Advanta;Офисные пакеты Microsoft Office, Open Office, Apple iWork;Редакторы кода Kate и VS Code для создания документов в Markdown, JSON и т.п.;Обработка фото в Adobe Camera Raw и Light Room;Веб-сервисы Google Workspace, Confluence, Trello, Asana, Jira;Искуственный интеллект ChatGPT, DeepSeek, Алиса. Владение языкамиАнглийским владею свободно Семейное положениеЖенат, двое детей УвлеченияСноуборд, велопоходы, игра на барабанах в рок-группе</li></ul>',13)])])}const u=e(o,[["render",t]]);export{p as __pageData,u as default};
